// Imports the web party game's data into the Apple TV app.
//   ../party-game/puzzles.js  -> src/data.js (BOOKS, SERIES, PUZZLES, WATCH, UNDISCLOSED)
//   ../party-game/glossary.js -> src/data.js (GLOSSARY)
//   ../party-game/qr-*.svg    -> assets/qr/qr-*.png   (tvOS has no SVG support built in)
//   ../party-game/covers/*    -> assets/covers/*
//   ../party-game/icon-130.png -> assets/logo-130.png
// The generated files are committed, so if the party-game folder is not next to
// this app (for example a build machine that only has this folder) it keeps them.
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync, copyFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import vm from "node:vm";
import zlib from "node:zlib";

const here = dirname(fileURLToPath(import.meta.url));
const app = join(here, "..");
const game = join(app, "..", "party-game");
const out = join(app, "src", "data.js");

if (!existsSync(join(game, "puzzles.js")) || !existsSync(join(game, "glossary.js"))) {
  if (existsSync(out)) {
    console.log("party-game folder not found; keeping the committed src/data.js.");
    process.exit(0);
  }
  throw new Error("party-game folder not found next to appletv-app, and src/data.js is missing.");
}

/* ---------- data ---------- */
const src = readFileSync(join(game, "puzzles.js"), "utf8") + "\n" + readFileSync(join(game, "glossary.js"), "utf8") +
  "\n;({ BOOKS, SERIES, PUZZLES, WATCH, UNDISCLOSED, GLOSSARY })";
const data = vm.runInNewContext(src, {}, { filename: "party-game-data.js" });

const isRegExp = (v) => Object.prototype.toString.call(v) === "[object RegExp]";
function lit(v, pad = "") {
  if (isRegExp(v)) return v.toString();
  if (Array.isArray(v)) {
    if (v.every((x) => !x || typeof x !== "object" || isRegExp(x))) return "[" + v.map((x) => lit(x)).join(", ") + "]";
    return "[\n" + v.map((x) => pad + "  " + lit(x, pad + "  ")).join(",\n") + "\n" + pad + "]";
  }
  if (v && typeof v === "object") {
    return "{ " + Object.entries(v).map(([k, x]) => `${/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k)}: ${lit(x, pad + "  ")}`).join(", ") + " }";
  }
  return JSON.stringify(v);
}
// Sanity checks so a broken source file doesn't silently produce an empty game.
if (!data.PUZZLES.length || !Object.keys(data.BOOKS).length || !data.GLOSSARY.length) throw new Error("party-game data looks empty");
for (const p of data.PUZZLES) {
  if (!data.BOOKS[p.book]) throw new Error(`Puzzle with unknown book: ${p.book}`);
  if (p.type !== "tf" && (!p.ingredients || !p.options || !p.spotlight)) throw new Error(`Incomplete puzzle: ${p.answer}`);
}

const js = `// Generated by scripts/import-data.mjs from ../party-game/puzzles.js and glossary.js.
// Do not edit by hand: change the web game, then run \`npm run import-data\`.
/* eslint-disable */

export const BOOKS = ${lit(data.BOOKS)};

export const SERIES = ${lit(data.SERIES)};

export const PUZZLES = ${lit(data.PUZZLES)};

export const WATCH = ${lit(data.WATCH)};

export const UNDISCLOSED = ${lit(data.UNDISCLOSED)};

export const GLOSSARY = ${lit(data.GLOSSARY)};

// { level: "warn" | "unknown", tag } or null
export function watchInfo(ingredient) {
  let hit = WATCH.find(([re]) => re.test(ingredient));
  if (hit) return { level: "warn", tag: hit[1] };
  hit = UNDISCLOSED.find(([re]) => re.test(ingredient));
  return hit ? { level: "unknown", tag: hit[1] } : null;
}

export function glossaryFor(ingredient) {
  const hit = GLOSSARY.find(([re]) => re.test(ingredient));
  return hit ? hit[1] : "No extra details for this one.";
}
`;
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, js);
console.log(`src/data.js: ${data.PUZZLES.length} puzzles, ${Object.keys(data.BOOKS).length} books, ${data.GLOSSARY.length} glossary rules.`);

/* ---------- pictures ---------- */
const covers = join(app, "assets", "covers");
mkdirSync(covers, { recursive: true });
for (const b of Object.values(data.BOOKS)) {
  copyFileSync(join(game, b.cover), join(covers, b.cover.split("/").pop()));
}
copyFileSync(join(game, "icon-130.png"), join(app, "assets", "logo-130.png"));

/* ---------- QR codes: SVG squares -> PNG ---------- */
const crcTable = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
function chunk(type, body) {
  const len = Buffer.alloc(4); len.writeUInt32BE(body.length);
  const tb = Buffer.concat([Buffer.from(type, "ascii"), body]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(tb));
  return Buffer.concat([len, tb, crc]);
}
// 8-bit grayscale PNG from a function (x, y) -> 0..255
function grayPng(w, h, px) {
  const raw = Buffer.alloc((w + 1) * h);
  for (let y = 0; y < h; y++) {
    raw[y * (w + 1)] = 0;
    for (let x = 0; x < w; x++) raw[y * (w + 1) + 1 + x] = px(x, y);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; ihdr[9] = 0; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr), chunk("IDAT", zlib.deflateSync(raw, { level: 9 })), chunk("IEND", Buffer.alloc(0))]);
}
const qrDir = join(app, "assets", "qr");
mkdirSync(qrDir, { recursive: true });
const qrFiles = readdirSync(game).filter((f) => /^qr-.*\.svg$/.test(f));
for (const f of qrFiles) {
  const svg = readFileSync(join(game, f), "utf8");
  const vb = svg.match(/viewBox="0 0 (\d+) (\d+)"/);
  if (!vb) throw new Error(`${f}: no viewBox`);
  const n = Number(vb[1]);
  const grid = Array.from({ length: n }, () => new Uint8Array(n));
  let count = 0;
  for (const m of svg.matchAll(/M(\d+),(\d+)H(\d+)V(\d+)H\d+z/g)) {
    const [x0, y0, x1, y1] = m.slice(1).map(Number);
    for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) grid[y][x] = 1;
    count++;
  }
  if (!count) throw new Error(`${f}: no QR squares found`);
  const S = 12;   // pixels per module -> 492 px for a 41-module code
  writeFileSync(join(qrDir, f.replace(/\.svg$/, ".png")),
    grayPng(n * S, n * S, (x, y) => (grid[Math.floor(y / S)][Math.floor(x / S)] ? 0 : 255)));
}
console.log(`assets: ${Object.keys(data.BOOKS).length} covers, ${qrFiles.length} QR codes.`);
